import{_ as i,a0 as p,w as l,s as d,I as n,x as a,a1 as e,A as o,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const q=JSON.parse('{"title":"使用 VS Code 進行 Python 編程 | LCTT x X-CMD","titleTemplate":false,"description":"使用 VS Code 進行 Python 編程 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 VS Code 進行 Python 編程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 VS Code 進行 Python 編程 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180730 How to use VS Code for your Python projects","title":"使用 VS Code 進行 Python 編程","tag":"201809","desc":""},"relativePath":"201809/20180730 How to use VS Code for your Python projects.md","filePath":"[post].md"}'),h={name:"201809/20180730 How to use VS Code for your Python projects.md"};function u(g,s,c,k,f,b){const t=p("Link");return l(),d("div",null,[s[18]||(s[18]=n("h1",{id:"使用-vs-code-進行-python-編程",tabindex:"-1"},[a("使用 VS Code 進行 Python 編程 "),n("a",{class:"header-anchor",href:"#使用-vs-code-進行-python-編程","aria-label":"Permalink to “使用 VS Code 進行 Python 編程”"},"​")],-1)),s[19]||(s[19]=n("p",null,[n("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/07/pythonvscode-816x345.jpg",alt:""})],-1)),s[20]||(s[20]=n("p",null,"Visual Studio Code，簡稱 VS Code，是一個開源的文本編輯器，包含用於構建和調試應用程序的工具。安裝啓用 Python 擴展後，VS Code 可以配置成理想的 Python 開發工作環境。本文將介紹一些有用的 VS Code 擴展，並配置它們以充分提高 Python 開發效率。",-1)),n("p",null,[s[1]||(s[1]=a("如果你的計算機上還沒有安裝 VS Code，可以參考文章 ",-1)),e(t,{href:"https://fedoramagazine.org/using-visual-studio-code-fedora/"},{default:o(()=>[...s[0]||(s[0]=[a("在 Fedora 上使用 VS Code",-1)])]),_:1}),s[2]||(s[2]=a(" 來安裝。",-1))]),s[21]||(s[21]=r(`<h3 id="在-vs-code-中安裝-python-擴展" tabindex="-1">在 VS Code 中安裝 Python 擴展 <a class="header-anchor" href="#在-vs-code-中安裝-python-擴展" aria-label="Permalink to “在 VS Code 中安裝 Python 擴展”">​</a></h3><p>首先，為了更方便地在 VS Code 中進行 Python 開發，需要從 VS Code 擴展商店中安裝 Python 擴展。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/07/Peek-2018-07-27-09-44.gif" alt=""></p><p>Python 擴展安裝完成後，就可以開始配置 Python 擴展了。</p><p>VS Code 通過兩個 JSON 文件管理設置:</p><ul><li>一個文件用於 VS Code 的全局設置，作用於所有的項目</li><li>另一個文件用於特殊設置，作用於單獨項目</li></ul><p>可以用快捷鍵 <code>Ctrl+,</code> （逗號）打開全局設置，也可以通過 <strong>文件 -&gt; 首選項 -&gt; 設置</strong> 來打開。</p><h4 id="設置-python-路徑" tabindex="-1">設置 Python 路徑 <a class="header-anchor" href="#設置-python-路徑" aria-label="Permalink to “設置 Python 路徑”">​</a></h4><p>您可以在全局設置中配置 <code>python.pythonPath</code> 使 VS Code 自動為每個項目選擇最適合的 Python 解釋器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// 將設置放在此處以覆蓋默認設置和用户設置。</span></span>
<span class="line"><span>// Path to Python, you can use a custom version of Python by modifying this setting to include the full path.</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;python.pythonPath&quot;:&quot;\${workspaceRoot}/.venv/bin/python&quot;,</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>這樣，VS Code 將使用虛擬環境目錄 <code>.venv</code> 下項目根目錄中的 Python 解釋器。</p><h4 id="使用環境變量" tabindex="-1">使用環境變量 <a class="header-anchor" href="#使用環境變量" aria-label="Permalink to “使用環境變量”">​</a></h4><p>默認情況下，VS Code 使用項目根目錄下的 <code>.env</code> 文件中定義的環境變量。 這對於設置環境變量很有用，如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PYTHONWARNINGS=&quot;once&quot;</span></span></code></pre></div><p>可使程序在運行時顯示警告。</p><p>可以通過設置 <code>python.envFile</code> 來加載其他的默認環境變量文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// Absolute path to a file containing environment variable definitions.</span></span>
<span class="line"><span>&quot;python.envFile&quot;: &quot;\${workspaceFolder}/.env&quot;,</span></span></code></pre></div><h3 id="代碼分析" tabindex="-1">代碼分析 <a class="header-anchor" href="#代碼分析" aria-label="Permalink to “代碼分析”">​</a></h3><p>Python 擴展還支持不同的代碼分析工具（pep8、flake8、pylint）。要啓用你喜歡的或者正在進行的項目所使用的分析工具，只需要進行一些簡單的配置。</p><p>擴展默認情況下使用 pylint 進行代碼分析。你可以這樣配置以使用 flake8 進行分析：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;python.linting.pylintEnabled&quot;: false,</span></span>
<span class="line"><span>&quot;python.linting.flake8Path&quot;: &quot;\${workspaceRoot}/.venv/bin/flake8&quot;,</span></span>
<span class="line"><span>&quot;python.linting.flake8Enabled&quot;: true,</span></span>
<span class="line"><span>&quot;python.linting.flake8Args&quot;: [&quot;--max-line-length=90&quot;],</span></span></code></pre></div><p>啓用代碼分析後，分析器會在不符合要求的位置加上波浪線，鼠標置於該位置，將彈窗提示其原因。注意，項目的虛擬環境中需要安裝有 flake8，此示例方能有效。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/07/Peek-2018-07-27-12-05.gif" alt=""></p><h3 id="格式化代碼" tabindex="-1">格式化代碼 <a class="header-anchor" href="#格式化代碼" aria-label="Permalink to “格式化代碼”">​</a></h3><p>可以配置 VS Code 使其自動格式化代碼。目前支持 autopep8、black 和 yapf。下面的設置將啓用 “black” 模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// Provider for formatting. Possible options include &#39;autopep8&#39;, &#39;black&#39;, and &#39;yapf&#39;.</span></span>
<span class="line"><span>&quot;python.formatting.provider&quot;: &quot;black&quot;,</span></span>
<span class="line"><span>&quot;python.formatting.blackPath&quot;: &quot;\${workspaceRoot}/.venv/bin/black&quot;</span></span>
<span class="line"><span>&quot;python.formatting.blackArgs&quot;: [&quot;--line-length=90&quot;],</span></span>
<span class="line"><span>&quot;editor.formatOnSave&quot;: true,</span></span></code></pre></div><p>如果不需要編輯器在保存時自動格式化代碼，可以將 <code>editor.formatOnSave</code> 設置為 <code>false</code> 並手動使用快捷鍵 <code>Ctrl + Shift + I</code> 格式化當前文檔中的代碼。 注意，項目的虛擬環境中需要安裝有 black，此示例方能有效。</p><h3 id="運行任務" tabindex="-1">運行任務 <a class="header-anchor" href="#運行任務" aria-label="Permalink to “運行任務”">​</a></h3><p>VS Code 的一個重要特點是它可以運行任務。需要運行的任務保存在項目根目錄中的 JSON 文件中。</p><h4 id="運行-flask-開發服務" tabindex="-1">運行 flask 開發服務 <a class="header-anchor" href="#運行-flask-開發服務" aria-label="Permalink to “運行 flask 開發服務”">​</a></h4><p>這個例子將創建一個任務來運行 Flask 開發服務器。 使用一個可以運行外部命令的基本模板來創建新的工程：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/07/Peek-2018-07-27-13-26.gif" alt=""></p><p>編輯如下所示的 <code>tasks.json</code> 文件，創建新任務來運行 Flask 開發服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>  // See https://go.microsoft.com/fwlink/?LinkId=733558</span></span>
<span class="line"><span>  // for the documentation about the tasks.json format</span></span>
<span class="line"><span>  &quot;version&quot;: &quot;2.0.0&quot;,</span></span>
<span class="line"><span>  &quot;tasks&quot;: [</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      &quot;label&quot;: &quot;Run Debug Server&quot;,</span></span>
<span class="line"><span>      &quot;type&quot;: &quot;shell&quot;,</span></span>
<span class="line"><span>      &quot;command&quot;: &quot;\${workspaceRoot}/.venv/bin/flask run -h 0.0.0.0 -p 5000&quot;,</span></span>
<span class="line"><span>      &quot;group&quot;: {</span></span>
<span class="line"><span>          &quot;kind&quot;: &quot;build&quot;,</span></span>
<span class="line"><span>          &quot;isDefault&quot;: true</span></span>
<span class="line"><span>       }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Flask 開發服務使用環境變量來獲取應用程序的入口點。 如 <strong>使用環境變量</strong> 一節所説，可以在 <code>.env</code> 文件中聲明這些變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>FLASK_APP=wsgi.py</span></span>
<span class="line"><span>FLASK_DEBUG=True</span></span></code></pre></div><p>這樣就可以使用快捷鍵 <code>Ctrl + Shift + B</code> 來執行任務了。</p><h3 id="單元測試" tabindex="-1">單元測試 <a class="header-anchor" href="#單元測試" aria-label="Permalink to “單元測試”">​</a></h3><p>VS Code 還支持單元測試框架 pytest、unittest 和 nosetest。啓用測試框架後，可以在 VS Code 中單獨運行搜索到的單元測試，通過測試套件運行測試或者運行所有的測試。</p><p>例如，可以這樣啓用 pytest 測試框架：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;python.unitTest.pyTestEnabled&quot;: true,</span></span>
<span class="line"><span>&quot;python.unitTest.pyTestPath&quot;: &quot;\${workspaceRoot}/.venv/bin/pytest&quot;,</span></span></code></pre></div><p>注意，項目的虛擬環境中需要安裝有 pytest，此示例方能有效。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/07/Peek-2018-07-27-15-33.gif" alt=""></p><hr>`,44)),n("p",null,[s[4]||(s[4]=a("via: ",-1)),e(t,{href:"https://fedoramagazine.org/vscode-python-howto/"},{default:o(()=>[...s[3]||(s[3]=[a("https://fedoramagazine.org/vscode-python-howto/",-1)])]),_:1})]),n("p",null,[s[9]||(s[9]=a("作者：",-1)),e(t,{href:"https://fedoramagazine.org"},{default:o(()=>[...s[5]||(s[5]=[a("Clément Verna",-1)])]),_:1}),s[10]||(s[10]=a(" 選題：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:o(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 譯者：",-1)),e(t,{href:"https://github.com/idea2act"},{default:o(()=>[...s[7]||(s[7]=[a("idea2act",-1)])]),_:1}),s[12]||(s[12]=a(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:o(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=a("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:o(()=>[...s[14]||(s[14]=[a("Linux中國",-1)])]),_:1}),s[17]||(s[17]=a(" 榮譽推出",-1))])])}const C=i(h,[["render",u]]);export{q as __pageData,C as default};
